insert or ignore into items (id, kind, slug, status, body, publish_at, created_at, updated_at) values ('28c1b598-c736-4a64-9986-9217abc790e5', 'news', 'rv-lot-fee', 'published', '{"title":"The RV lot is no longer free","summary":"From 1 October 2025 the lot costs $50 a month, or $150 a quarter paid with your assessment.","body":"The association now charges for the RV lot. The fee is **$50 per month per\nhousehold**, or **$150 per quarter** paid alongside your quarterly assessment.\n\nPay by Zelle, with **RV Lot Payment** in the memo line.\n\nA few rules came in at the same time: one vehicle per household, current\nregistration on every vehicle, and keep both the vehicle and the space around it\ntidy.\n\nThe fee is what will pay for repairing the fence, repainting the lines and space\nnumbers, and improving security. Full details are on the\n[RV lot page](/amenities/rv-lot/).","category":"general","pinned":false}', '2025-08-11T09:00:00-04:00', '2026-09-17T06:53:26.998Z', '2026-09-17T06:53:26.998Z');
insert or ignore into items (id, kind, slug, status, body, publish_at, created_at, updated_at) values ('efd85b0d-3daf-4b79-97fe-fff13fbfdead', 'news', 'water-main-phase-1', 'published', '{"title":"Water main replacement: what Phase 1 affects","summary":"Six streets are in Phase 1. Expect construction traffic and occasional short water interruptions.","body":"Phase 1 of the water main replacement covers Inspiration Court, both stretches of\nInspiration Avenue, Triumphant Court, Successful Way, and Curiosity Court.\n\nIf you live on one of those streets, expect construction traffic and the\noccasional short interruption to your water supply. Notices go out ahead of any\nplanned shut-off.\n\nThe full plan-and-profile drawings are in the [document library](/documents/),\nand the [projects page](/board/projects/) tracks where things stand.","category":"maintenance","pinned":false}', '2026-02-10T09:00:00-05:00', '2026-09-17T06:53:26.998Z', '2026-09-17T06:53:26.998Z');
insert or ignore into items (id, kind, slug, status, body, publish_at, created_at, updated_at) values ('cee23375-8099-4c37-9401-d7502013260c', 'news', 'pool-season-2026', 'published', '{"title":"Pool passes for 2026 are on sale","summary":"Early-bird pricing runs until 15 April. After that the resident rate goes up by $10 a head.","body":"Registration for the 2026 pool season is open. Early-bird pricing — **$35 per\nperson** — runs until **15 April**. After that it is $45.\n\nChildren five and under swim free. You need to be current on your assessment to\nbuy a pool membership.\n\nSeason dates, hours, and the fee tables are on the [pool page](/amenities/pool/).","category":"pool","pinned":true}', '2026-03-01T09:00:00-05:00', '2026-09-17T06:53:26.998Z', '2026-09-17T06:53:26.998Z');
insert or ignore into items (id, kind, slug, status, body, publish_at, created_at, updated_at) values ('508b97d1-1ae7-4c98-8103-4ddacf4a5c07', 'event', 'ladies-day-out', 'published', '{"title":"Ladies Day Out","summary":"An afternoon at the Recreation Center. Bring a neighbor.","body":"","start":"2026-04-25T14:00:00-04:00","end":"2026-04-25T16:00:00-04:00","location":"Discovery Recreation Center","cost":"Free","audience":"Open to all Discovery residents","contact_email_key":"pool_rec"}', '2026-03-01T09:00:00-05:00', '2026-09-17T06:53:26.998Z', '2026-09-17T06:53:26.998Z');
