insert or ignore into items (id, kind, slug, status, body, publish_at, created_at, updated_at) values ('6480dd29-9bc6-4a6d-8902-82fbcce87283', 'event', 'pool-opening', 'published', '{"title":"Pool Opening — Free Open House","summary":"The first swim of the season, and no pass needed on opening day.","body":"The pool opens for the 2026 season. Opening day is a free open house, so you can\ncome and look even if you have not bought a pass yet.\n\nPasses for the season are on sale — see the [pool page](/amenities/pool/) for\nfees and registration.","start":"2026-05-23T12:00:00-04:00","end":"2026-05-23T20:00:00-04:00","location":"Discovery Community Pool","cost":"Free","audience":"Everyone","contact_email_key":"pool_rec"}', '2026-03-01T09:00:00-05:00', '2026-09-17T06:53:26.998Z', '2026-09-17T06:53:26.998Z');
