gin.","Enter your email address.","Confirm your name and property address.","Your request goes to the HOA office for approval.","Once approved, create a password and sign in."],"fees":[{"method":"Bank account (ACH)","amount":"$2.45 per transaction"},{"method":"Credit card","amount":"3.5% + $0.50 per transaction"}],"fees_note":"These processing fees are charged by PayHOA, not by the association.","offline_note":"The office still accepts cash, check, and bank bill-pay.","minutes_note":"Approved board meeting minutes are posted in the resident portal."},"pool_registration":{"label":"Register for a pool pass","url":"https://swimmingpoolpasses.net/discovery-community-pool/","vendor":"Access Granted Systems"},"county_recycling":{"label":"Frederick County collection schedule","url":"https://frederickcountymd.gov/3447/Curbside-Collection-Schedule"},"water_bill":{"label":"Pay your Walkersville water bill","url":"https://www.walkersvillemd.gov/"}},"newsletter":{"enabled":false,"provider":"sender"}}', '2026-09-17T06:53:26.998Z');
insert or ignore into settings (key, value, updated_at) values ('parks', '{"count":20,"inspection_note":"An outside inspector reviews all twenty parks each year, usually in late July or early August, checking equipment for safety and wear.","report_note":"If a swing, slide, or bench is broken or looks unsafe, tell the office. It is logged and scheduled rather than waiting for the annual inspection."}', '2026-09-17T06:53:26.998Z');
